SELECT CASE WHEN s.rating >= 3.4 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(p.launch_date) AS latest_launch_date FROM products p JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 3.4 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END;
